-- AITS PostgreSQL schema
-- PostgreSQL 18+
-- This file is intentionally idempotent. The Go server may apply it every
-- startup so a fresh AITS installation can recreate the same base structure.

BEGIN;

CREATE TABLE IF NOT EXISTS schema_state (
    key         TEXT PRIMARY KEY,
    value       TEXT NOT NULL,
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO schema_state (key, value)
VALUES ('schema_version', '6')
ON CONFLICT (key) DO UPDATE
SET value = EXCLUDED.value,
    updated_at = NOW();

CREATE TABLE IF NOT EXISTS accounts (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username        VARCHAR(64),
    email           VARCHAR(320),
    password_hash   TEXT,
    display_name    VARCHAR(160) NOT NULL,
    avatar_url      TEXT,
    account_kind    VARCHAR(20) NOT NULL DEFAULT 'visitor'
                    CHECK (account_kind IN ('visitor', 'member', 'system')),
    status          VARCHAR(20) NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active', 'pending', 'restricted', 'disabled')),
    last_login_at   TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS accounts_username_unique
    ON accounts (LOWER(username)) WHERE username IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS accounts_email_unique
    ON accounts (LOWER(email)) WHERE email IS NOT NULL;


-- System publishing identities used by the synchronized public/member sample feed.
-- They are not login accounts and do not contain credentials.
INSERT INTO accounts (username, display_name, account_kind, status)
VALUES
    ('aits_official', 'AITS', 'system', 'active'),
    ('codehex_official', 'CodeHex', 'system', 'active'),
    ('illustrados_official', 'Illustrados', 'system', 'active'),
    ('neotech_official', 'Neo-Tech', 'system', 'active')
ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS oauth_identities (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id          BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    provider            VARCHAR(20) NOT NULL CHECK (provider IN ('google', 'github')),
    provider_user_id    TEXT NOT NULL,
    provider_email      VARCHAR(320),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (provider, provider_user_id)
);


-- Short-lived OAuth state and localhost handoff records make visitor sign-in
-- work consistently when development runs at 127.0.0.1 while the registered
-- OAuth callback remains https://aits.jpano.dev. Raw secrets are never stored.
CREATE TABLE IF NOT EXISTS oauth_states (
    state_hash      CHAR(64) PRIMARY KEY,
    provider        VARCHAR(20) NOT NULL CHECK (provider IN ('google', 'github')),
    return_path     TEXT NOT NULL DEFAULT '/',
    client_origin   TEXT NOT NULL DEFAULT 'https://aits.jpano.dev',
    expires_at      TIMESTAMPTZ NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS oauth_states_expiry_idx ON oauth_states(expires_at);

CREATE TABLE IF NOT EXISTS oauth_handoffs (
    token_hash      CHAR(64) PRIMARY KEY,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    provider        VARCHAR(20) NOT NULL CHECK (provider IN ('google', 'github')),
    client_origin   TEXT NOT NULL,
    expires_at      TIMESTAMPTZ NOT NULL,
    used_at         TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS oauth_handoffs_expiry_idx ON oauth_handoffs(expires_at) WHERE used_at IS NULL;


-- Member sessions are persisted as hashes so installed/mobile web-app sessions
-- survive browser navigation and backend restarts until logout or expiry.
CREATE TABLE IF NOT EXISTS member_sessions (
    token_hash      CHAR(64) PRIMARY KEY,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    expires_at      TIMESTAMPTZ NOT NULL,
    last_seen_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS member_sessions_account_idx ON member_sessions(account_id);
CREATE INDEX IF NOT EXISTS member_sessions_expiry_idx ON member_sessions(expires_at);

CREATE TABLE IF NOT EXISTS divisions (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code            VARCHAR(40) NOT NULL UNIQUE,
    name            VARCHAR(100) NOT NULL UNIQUE,
    description     TEXT,
    logo_url        TEXT,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    sort_order      INTEGER NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO divisions (code, name, sort_order)
VALUES
    ('codehex', 'CodeHex', 10),
    ('illustrados', 'Illustrados', 20),
    ('neo-tech', 'Neo-Tech', 30)
ON CONFLICT (code) DO UPDATE
SET name = EXCLUDED.name,
    sort_order = EXCLUDED.sort_order;

CREATE TABLE IF NOT EXISTS roles (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code                VARCHAR(50) NOT NULL UNIQUE,
    name                VARCHAR(100) NOT NULL,
    hierarchy_level     INTEGER NOT NULL DEFAULT 0,
    scope               VARCHAR(20) NOT NULL DEFAULT 'global'
                        CHECK (scope IN ('global', 'division')),
    is_administrator    BOOLEAN NOT NULL DEFAULT FALSE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO roles (code, name, hierarchy_level, scope, is_administrator)
VALUES
    ('developer', 'Developer', 100, 'global', TRUE),
    ('instructor', 'Adviser', 90, 'global', TRUE),
    ('president', 'President', 80, 'global', TRUE),
    ('vice_president', 'Vice President', 70, 'global', TRUE),
    ('secretary', 'Secretary', 60, 'global', TRUE),
    ('treasurer', 'Treasurer', 60, 'global', TRUE),
    ('pio', 'Public Information Officer', 60, 'global', TRUE),
    ('mayor', 'Division Mayor', 50, 'division', TRUE),
    ('member', 'Member', 10, 'global', FALSE)
ON CONFLICT (code) DO UPDATE
SET name = EXCLUDED.name,
    hierarchy_level = EXCLUDED.hierarchy_level,
    scope = EXCLUDED.scope,
    is_administrator = EXCLUDED.is_administrator;

CREATE TABLE IF NOT EXISTS permissions (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        VARCHAR(80) NOT NULL UNIQUE,
    name        VARCHAR(120) NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO permissions (code, name)
VALUES
    ('admin.access', 'Access administration'),
    ('applications.manage', 'Manage applications'),
    ('members.manage', 'Manage members'),
    ('posts.manage', 'Manage posts'),
    ('divisions.manage', 'Manage divisions'),
    ('administration.manage', 'Manage administration directory'),
    ('tests.manage', 'Manage assessments'),
    ('academic.manage', 'Manage academic structure'),
    ('access.manage', 'Manage roles and permissions'),
    ('settings.manage', 'Manage system settings'),
    ('community.post', 'Create community posts'),
    ('community.chat', 'Use community chat')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name;

CREATE TABLE IF NOT EXISTS role_permissions (
    role_id         BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    permission_id   BIGINT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (role_id, permission_id)
);

-- Developer is intentionally granted every registered permission.
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM roles r
CROSS JOIN permissions p
WHERE r.code = 'developer'
ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS account_roles (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    role_id         BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    division_id     BIGINT REFERENCES divisions(id) ON DELETE CASCADE,
    granted_by      BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    starts_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS account_roles_unique_scope
    ON account_roles (account_id, role_id, COALESCE(division_id, 0));

CREATE TABLE IF NOT EXISTS member_profiles (
    account_id          BIGINT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
    member_number       VARCHAR(80) UNIQUE,
    department          VARCHAR(160),
    course              VARCHAR(160),
    year_level          VARCHAR(80),
    primary_division_id BIGINT REFERENCES divisions(id) ON DELETE SET NULL,
    biography           TEXT,
    membership_level    VARCHAR(40) NOT NULL DEFAULT 'Member',
    birth_date          DATE,
    gender              VARCHAR(40),
    contact_number      VARCHAR(80),
    facebook_url        TEXT,
    instagram_url       TEXT,
    github_url          TEXT,
    joined_at           DATE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS membership_level VARCHAR(40) NOT NULL DEFAULT 'Member';
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS birth_date DATE;
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS gender VARCHAR(40);
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS contact_number VARCHAR(80);
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS facebook_url TEXT;
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS instagram_url TEXT;
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS github_url TEXT;

CREATE TABLE IF NOT EXISTS administration_members (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    category        VARCHAR(20) NOT NULL CHECK (category IN ('adviser', 'officer')),
    position_title  VARCHAR(120) NOT NULL,
    division_id     BIGINT REFERENCES divisions(id) ON DELETE SET NULL,
    public_email    BOOLEAN NOT NULL DEFAULT FALSE,
    public_message  TEXT,
    sort_order      INTEGER NOT NULL DEFAULT 0,
    is_published    BOOLEAN NOT NULL DEFAULT TRUE,
    starts_on       DATE,
    ends_on         DATE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);



CREATE TABLE IF NOT EXISTS administration_member_positions (
    administration_member_id BIGINT NOT NULL REFERENCES administration_members(id) ON DELETE CASCADE,
    position_title           VARCHAR(120) NOT NULL,
    sort_order               INTEGER NOT NULL DEFAULT 0,
    created_at               TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at               TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (administration_member_id, position_title)
);

INSERT INTO administration_member_positions (administration_member_id, position_title, sort_order)
SELECT id, position_title, 0
FROM administration_members
ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS announcements (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    seed_key        VARCHAR(100) UNIQUE,
    announcement_type VARCHAR(80) NOT NULL DEFAULT 'General',
    title           VARCHAR(220) NOT NULL,
    description     TEXT NOT NULL,
    status_tone     VARCHAR(20) NOT NULL DEFAULT 'info'
                    CHECK (status_tone IN ('info', 'success', 'warning', 'danger')),
    action_label    VARCHAR(120),
    action_href     TEXT,
    is_published    BOOLEAN NOT NULL DEFAULT TRUE,
    published_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS announcements_published_idx
    ON announcements (is_published, published_at DESC);

