CREATE TABLE IF NOT EXISTS applications (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_number  VARCHAR(40) NOT NULL UNIQUE,
    account_id          BIGINT NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
    assessment_mode     VARCHAR(20) NOT NULL DEFAULT 'discovery'
                        CHECK (assessment_mode IN ('discovery', 'specific')),
    target_division_id  BIGINT REFERENCES divisions(id) ON DELETE SET NULL,
    birth_date          DATE,
    department          VARCHAR(160),
    course              VARCHAR(160),
    year_level          VARCHAR(80),
    reason              TEXT,
    status              VARCHAR(30) NOT NULL DEFAULT 'draft'
                        CHECK (status IN ('draft', 'submitted', 'for_review', 'for_interview', 'accepted', 'declined', 'cancelled')),
    submitted_at        TIMESTAMPTZ,
    reviewed_at         TIMESTAMPTZ,
    reviewed_by         BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS applications_account_idx ON applications(account_id);
CREATE INDEX IF NOT EXISTS applications_status_idx ON applications(status);

CREATE TABLE IF NOT EXISTS assessment_questions (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category        VARCHAR(20) NOT NULL CHECK (category IN ('general', 'division')),
    division_id     BIGINT REFERENCES divisions(id) ON DELETE CASCADE,
    prompt          TEXT NOT NULL,
    image_url       TEXT,
    explanation     TEXT,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK ((category = 'general' AND division_id IS NULL) OR (category = 'division' AND division_id IS NOT NULL))
);

CREATE TABLE IF NOT EXISTS assessment_choices (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    question_id     BIGINT NOT NULL REFERENCES assessment_questions(id) ON DELETE CASCADE,
    answer_text     TEXT NOT NULL,
    image_url       TEXT,
    is_correct      BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order      INTEGER NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS assessment_one_correct_choice
    ON assessment_choices(question_id) WHERE is_correct = TRUE;

CREATE TABLE IF NOT EXISTS assessment_attempts (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id      BIGINT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,
    assessment_mode     VARCHAR(20) NOT NULL CHECK (assessment_mode IN ('discovery', 'specific')),
    target_division_id  BIGINT REFERENCES divisions(id) ON DELETE SET NULL,
    status              VARCHAR(20) NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active', 'completed', 'abandoned')),
    total_questions     INTEGER NOT NULL DEFAULT 0,
    correct_answers     INTEGER NOT NULL DEFAULT 0,
    overall_score       NUMERIC(5,2),
    general_score       NUMERIC(5,2),
    division_score      NUMERIC(5,2),
    response_speed_ms   NUMERIC(12,2),
    focus_incidents     INTEGER NOT NULL DEFAULT 0,
    started_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at        TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS assessment_attempt_items (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    attempt_id          BIGINT NOT NULL REFERENCES assessment_attempts(id) ON DELETE CASCADE,
    question_id         BIGINT NOT NULL REFERENCES assessment_questions(id) ON DELETE RESTRICT,
    position            INTEGER NOT NULL,
    is_reserve          BOOLEAN NOT NULL DEFAULT FALSE,
    selected_choice_id  BIGINT REFERENCES assessment_choices(id) ON DELETE SET NULL,
    is_correct          BOOLEAN,
    timed_out           BOOLEAN NOT NULL DEFAULT FALSE,
    response_ms         INTEGER,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (attempt_id, position)
);

CREATE TABLE IF NOT EXISTS posts (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    author_account_id   BIGINT NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
    body                TEXT NOT NULL,
    visibility          VARCHAR(20) NOT NULL DEFAULT 'organization'
                        CHECK (visibility IN ('organization', 'division', 'public')),
    moderation_status   VARCHAR(20) NOT NULL DEFAULT 'published'
                        CHECK (moderation_status IN ('pending', 'published', 'rejected', 'hidden')),
    is_pinned           BOOLEAN NOT NULL DEFAULT FALSE,
    published_at        TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


-- Columns shared by the public landing feed, member feed, and administrator view.
ALTER TABLE posts ADD COLUMN IF NOT EXISTS seed_key VARCHAR(100);
ALTER TABLE posts ADD COLUMN IF NOT EXISTS title VARCHAR(220);
ALTER TABLE posts ADD COLUMN IF NOT EXISTS author_label VARCHAR(160);
ALTER TABLE posts ADD COLUMN IF NOT EXISTS role_label VARCHAR(120);
ALTER TABLE posts ADD COLUMN IF NOT EXISTS division_id BIGINT REFERENCES divisions(id) ON DELETE SET NULL;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS media JSONB NOT NULL DEFAULT '[]'::JSONB;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS client_nonce VARCHAR(96);
ALTER TABLE posts ADD COLUMN IF NOT EXISTS identity_kind VARCHAR(20) NOT NULL DEFAULT 'member';
-- Backfill branded identity for older seeded/official posts created before identity_kind existed.
UPDATE posts SET identity_kind='organization' WHERE identity_kind='member' AND author_label='AITS';
UPDATE posts p SET identity_kind='division' WHERE p.identity_kind='member' AND p.division_id IS NOT NULL AND EXISTS (SELECT 1 FROM divisions d WHERE d.id=p.division_id AND LOWER(COALESCE(p.author_label,''))=LOWER(d.name));

ALTER TABLE posts DROP CONSTRAINT IF EXISTS posts_visibility_check;
UPDATE posts SET visibility = 'organization' WHERE visibility = 'community';
ALTER TABLE posts ALTER COLUMN visibility SET DEFAULT 'organization';
ALTER TABLE posts ADD CONSTRAINT posts_visibility_check
    CHECK (visibility IN ('organization', 'division', 'public'));

CREATE UNIQUE INDEX IF NOT EXISTS posts_seed_key_unique
    ON posts (seed_key) WHERE seed_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS posts_feed_idx
    ON posts (moderation_status, visibility, id DESC);
CREATE UNIQUE INDEX IF NOT EXISTS posts_author_client_nonce_unique
    ON posts (author_account_id, client_nonce)
    WHERE client_nonce IS NOT NULL;

