INSERT INTO posts (author_account_id, seed_key, title, body, visibility, moderation_status, is_pinned, published_at, author_label, role_label, division_id, media)
SELECT a.id, 'sample-post-05', 'Different strengths, shared direction', 'CodeHex, Illustrados, and Neo-Tech focus on different areas, but every division contributes to the same goal: helping students learn, collaborate, create, and participate in the wider AITS community.', 'public', 'published', FALSE, '2026-09-06 15:15:00+08'::timestamptz, 'AITS', 'Official', NULL, '[]'::jsonb
