CREATE TABLE IF NOT EXISTS post_comments (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    post_id             BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    author_account_id   BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    parent_comment_id   BIGINT REFERENCES post_comments(id) ON DELETE CASCADE,
    body                TEXT NOT NULL,
    status              VARCHAR(20) NOT NULL DEFAULT 'visible'
                        CHECK (status IN ('visible', 'hidden', 'deleted')),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE post_comments ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ;
ALTER TABLE post_comments ADD COLUMN IF NOT EXISTS client_nonce VARCHAR(96);
CREATE UNIQUE INDEX IF NOT EXISTS post_comments_author_client_nonce_unique
    ON post_comments (author_account_id, client_nonce)
    WHERE client_nonce IS NOT NULL;

CREATE TABLE IF NOT EXISTS post_comment_history (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    comment_id          BIGINT NOT NULL REFERENCES post_comments(id) ON DELETE CASCADE,
    editor_account_id   BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    body                TEXT NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS post_comment_history_comment_idx
    ON post_comment_history(comment_id, id DESC);

CREATE TABLE IF NOT EXISTS post_reactions (
    post_id             BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    account_id          BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    reaction            VARCHAR(24) NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (post_id, account_id)
);
UPDATE post_reactions SET reaction='❤️' WHERE reaction='like' OR BTRIM(reaction)='';

CREATE TABLE IF NOT EXISTS comment_reactions (
    comment_id          BIGINT NOT NULL REFERENCES post_comments(id) ON DELETE CASCADE,
    account_id          BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    reaction            VARCHAR(24) NOT NULL DEFAULT '❤️',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (comment_id, account_id)
);
ALTER TABLE comment_reactions ADD COLUMN IF NOT EXISTS reaction VARCHAR(24);
ALTER TABLE comment_reactions ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
UPDATE comment_reactions SET reaction='❤️' WHERE reaction IS NULL OR BTRIM(reaction)='';
ALTER TABLE comment_reactions ALTER COLUMN reaction SET DEFAULT '❤️';
ALTER TABLE comment_reactions ALTER COLUMN reaction SET NOT NULL;

CREATE TABLE IF NOT EXISTS notifications (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    notification_type VARCHAR(60) NOT NULL,
    title           VARCHAR(180) NOT NULL,
    body            TEXT,
    read_at         TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE notifications ADD COLUMN IF NOT EXISTS action_url VARCHAR(600);
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS target_post_id BIGINT;
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS target_comment_id BIGINT;

CREATE INDEX IF NOT EXISTS notifications_account_read_idx
    ON notifications(account_id, read_at);

CREATE TABLE IF NOT EXISTS conversations (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conversation_type VARCHAR(20) NOT NULL CHECK (conversation_type IN ('private', 'group', 'community')),
    title           VARCHAR(180),
    created_by      BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS conversation_members (
    conversation_id BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    member_role     VARCHAR(20) NOT NULL DEFAULT 'member' CHECK (member_role IN ('owner', 'moderator', 'member')),
    joined_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_read_at    TIMESTAMPTZ,
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (conversation_id, account_id)
);

CREATE TABLE IF NOT EXISTS messages (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conversation_id     BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    sender_account_id   BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    body                TEXT,
    attachment_url      TEXT,
    edited_at           TIMESTAMPTZ,
    deleted_at          TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (body IS NOT NULL OR attachment_url IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS messages_conversation_idx
    ON messages(conversation_id, created_at);


CREATE TABLE IF NOT EXISTS support_threads (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    visitor_account_id  BIGINT NOT NULL UNIQUE REFERENCES accounts(id) ON DELETE CASCADE,
    status              VARCHAR(20) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
    assigned_admin_id   BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    last_message_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS support_messages (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    thread_id           BIGINT NOT NULL REFERENCES support_threads(id) ON DELETE CASCADE,
    sender_account_id   BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    sender_kind         VARCHAR(20) NOT NULL CHECK (sender_kind IN ('visitor', 'admin')),
    body                TEXT NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS support_threads_activity_idx ON support_threads(last_message_at DESC);
CREATE INDEX IF NOT EXISTS support_messages_thread_idx ON support_messages(thread_id, id);

CREATE TABLE IF NOT EXISTS audit_logs (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_account_id BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    action          VARCHAR(120) NOT NULL,
    entity_type     VARCHAR(80),
    entity_id       TEXT,
    details         JSONB NOT NULL DEFAULT '{}'::JSONB,
    ip_address      INET,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


-- Member-managed labels and controlled profile-change workflows.
CREATE TABLE IF NOT EXISTS member_tags (
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    tag             VARCHAR(60) NOT NULL,
    sort_order      INTEGER NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (account_id, tag)
);

CREATE TABLE IF NOT EXISTS member_change_requests (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id              BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    request_type            VARCHAR(30) NOT NULL CHECK (request_type IN ('division')),
    requested_division_id   BIGINT REFERENCES divisions(id) ON DELETE SET NULL,
    status                  VARCHAR(20) NOT NULL DEFAULT 'pending'
                            CHECK (status IN ('pending', 'approved', 'declined', 'cancelled')),
    note                    TEXT,
    reviewed_by             BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    reviewed_at             TIMESTAMPTZ,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS member_change_requests_one_pending_division
    ON member_change_requests(account_id, request_type)
    WHERE status = 'pending';

CREATE TABLE IF NOT EXISTS account_security_codes (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    purpose         VARCHAR(30) NOT NULL CHECK (purpose IN ('password_change', 'password_recovery')),
    code_hash       TEXT NOT NULL,
    expires_at      TIMESTAMPTZ NOT NULL,
    used_at         TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS account_security_codes_lookup_idx
    ON account_security_codes(account_id, purpose, expires_at DESC);

-- Public/organizational asset registry. Private-message attachments are deliberately
-- excluded from this library and remain outside this table.
CREATE TABLE IF NOT EXISTS media_library (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    label           VARCHAR(180) NOT NULL,
    media_type      VARCHAR(30) NOT NULL DEFAULT 'image'
                    CHECK (media_type IN ('image', 'video', 'audio', 'document', 'link', 'other')),
    url             TEXT NOT NULL,
    visibility      VARCHAR(20) NOT NULL DEFAULT 'public'
                    CHECK (visibility IN ('public', 'organization', 'division')),
    division_id     BIGINT REFERENCES divisions(id) ON DELETE SET NULL,
    uploaded_by     BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS media_library_visibility_idx
    ON media_library(visibility, is_active, created_at DESC);
DROP INDEX IF EXISTS media_library_url_unique;
CREATE INDEX IF NOT EXISTS media_library_url_idx ON media_library(url);

INSERT INTO media_library(label,media_type,url,visibility,is_active)
SELECT seed.label,seed.media_type,seed.url,seed.visibility,seed.is_active
FROM (VALUES
    ('AITS community artwork','image','/imgs/blog-aits.svg','public',TRUE),
    ('CodeHex artwork','image','/imgs/blog-codehex.svg','public',TRUE),
    ('Illustrados artwork','image','/imgs/blog-illustrados.svg','public',TRUE),
    ('Neo-Tech artwork','image','/imgs/blog-neotech.svg','public',TRUE)
) AS seed(label,media_type,url,visibility,is_active)
WHERE NOT EXISTS (SELECT 1 FROM media_library current_item WHERE current_item.url=seed.url);

-- Keep application records rich enough for administration review.
ALTER TABLE applications ADD COLUMN IF NOT EXISTS gender VARCHAR(40);
ALTER TABLE applications ADD COLUMN IF NOT EXISTS school_id VARCHAR(100);
ALTER TABLE applications ADD COLUMN IF NOT EXISTS overall_score NUMERIC(5,2);
ALTER TABLE applications ADD COLUMN IF NOT EXISTS response_score NUMERIC(5,2);

COMMIT;

-- ===== AITS workspace expansion (2026-09) =====
BEGIN;
-- Member profile fields used by the profile editor.
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS first_name VARCHAR(80);
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS middle_name VARCHAR(80);
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS last_name VARCHAR(80);
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS extension_name VARCHAR(24);
ALTER TABLE member_profiles ADD COLUMN IF NOT EXISTS school_id VARCHAR(80);

-- Controlled membership-change requests alongside division changes.
ALTER TABLE member_change_requests DROP CONSTRAINT IF EXISTS member_change_requests_request_type_check;
ALTER TABLE member_change_requests ADD COLUMN IF NOT EXISTS requested_membership VARCHAR(40);

CREATE UNIQUE INDEX IF NOT EXISTS member_change_requests_one_pending_membership
    ON member_change_requests(account_id, request_type)
    WHERE status = 'pending' AND request_type='membership';

-- Verification codes can carry the pending value (for example a new email).
ALTER TABLE account_security_codes DROP CONSTRAINT IF EXISTS account_security_codes_purpose_check;
ALTER TABLE account_security_codes ADD COLUMN IF NOT EXISTS payload JSONB NOT NULL DEFAULT '{}'::JSONB;

-- One-time links generated by higher-ranked administrators for member password reset.
CREATE TABLE IF NOT EXISTS admin_password_reset_links (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    requested_by    BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    token_hash      TEXT NOT NULL UNIQUE,
    expires_at      TIMESTAMPTZ NOT NULL,
    used_at         TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS admin_password_reset_links_account_idx
    ON admin_password_reset_links(account_id, expires_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS admin_password_reset_links_one_active
    ON admin_password_reset_links(account_id)
    WHERE used_at IS NULL;

-- Conversation enhancements.
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS division_id BIGINT REFERENCES divisions(id) ON DELETE SET NULL;
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS reply_to_id BIGINT REFERENCES messages(id) ON DELETE SET NULL;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS attachments JSONB NOT NULL DEFAULT '[]'::JSONB;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS seen_at TIMESTAMPTZ;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS client_nonce VARCHAR(96);
ALTER TABLE messages ADD COLUMN IF NOT EXISTS pinned_at TIMESTAMPTZ;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS pinned_by BIGINT REFERENCES accounts(id) ON DELETE SET NULL;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS view_limit INTEGER CHECK (view_limit IS NULL OR (view_limit BETWEEN 1 AND 100));
ALTER TABLE messages ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ;
CREATE UNIQUE INDEX IF NOT EXISTS messages_sender_client_nonce_unique
    ON messages (conversation_id, sender_account_id, client_nonce)
    WHERE client_nonce IS NOT NULL AND sender_account_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS messages_expiry_idx
    ON messages (conversation_id, expires_at)
    WHERE expires_at IS NOT NULL;

CREATE TABLE IF NOT EXISTS message_views (
    message_id  BIGINT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
    account_id  BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    viewed_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (message_id, account_id)
);

CREATE TABLE IF NOT EXISTS message_reactions (
    message_id      BIGINT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    reaction        VARCHAR(32) NOT NULL DEFAULT 'like',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY(message_id,account_id,reaction)
);

-- Visitor-to-administration support enhancements.
ALTER TABLE support_messages ADD COLUMN IF NOT EXISTS reply_to_id BIGINT REFERENCES support_messages(id) ON DELETE SET NULL;
ALTER TABLE support_messages ADD COLUMN IF NOT EXISTS attachments JSONB NOT NULL DEFAULT '[]'::JSONB;
ALTER TABLE support_messages ADD COLUMN IF NOT EXISTS reply_identity JSONB NOT NULL DEFAULT '{}'::JSONB;
ALTER TABLE support_messages ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ;
ALTER TABLE support_threads ADD COLUMN IF NOT EXISTS visitor_ip TEXT;
ALTER TABLE support_threads ADD COLUMN IF NOT EXISTS visitor_user_agent TEXT;
ALTER TABLE support_threads ADD COLUMN IF NOT EXISTS visitor_fingerprint VARCHAR(64);
ALTER TABLE support_threads ADD COLUMN IF NOT EXISTS is_blocked BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE support_threads ADD COLUMN IF NOT EXISTS blocked_at TIMESTAMPTZ;
ALTER TABLE support_threads ADD COLUMN IF NOT EXISTS blocked_by BIGINT REFERENCES accounts(id) ON DELETE SET NULL;

CREATE TABLE IF NOT EXISTS support_message_reactions (
    message_id      BIGINT NOT NULL REFERENCES support_messages(id) ON DELETE CASCADE,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    reaction        VARCHAR(32) NOT NULL DEFAULT 'like',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY(message_id,account_id,reaction)
);

-- Shared library tracking. Private/support/chat attachments are not registered here.
ALTER TABLE media_library ADD COLUMN IF NOT EXISTS extension VARCHAR(20);
ALTER TABLE media_library ADD COLUMN IF NOT EXISTS location_label TEXT;
ALTER TABLE media_library ADD COLUMN IF NOT EXISTS reason TEXT;
ALTER TABLE media_library ADD COLUMN IF NOT EXISTS file_size BIGINT;
ALTER TABLE media_library ADD COLUMN IF NOT EXISTS source_type VARCHAR(20) NOT NULL DEFAULT 'path';
ALTER TABLE media_library ADD COLUMN IF NOT EXISTS content_hash VARCHAR(64);
CREATE INDEX IF NOT EXISTS media_library_content_hash_idx ON media_library(content_hash) WHERE content_hash IS NOT NULL;
ALTER TABLE media_library DROP CONSTRAINT IF EXISTS media_library_media_type_check;
ALTER TABLE media_library ADD CONSTRAINT media_library_media_type_check CHECK (media_type IN ('image','video','audio','file','document','link','other'));

CREATE TABLE IF NOT EXISTS media_library_usage (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    media_id        BIGINT NOT NULL REFERENCES media_library(id) ON DELETE CASCADE,
    account_id      BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    location_label  TEXT NOT NULL,
    action          VARCHAR(40) NOT NULL DEFAULT 'used',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE media_library_usage ADD COLUMN IF NOT EXISTS reason TEXT;
CREATE INDEX IF NOT EXISTS media_library_usage_media_idx ON media_library_usage(media_id,created_at DESC);

-- 30-day archive for records removed from active management views.
CREATE TABLE IF NOT EXISTS archive_items (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    entity_type     VARCHAR(40) NOT NULL,
    entity_id       TEXT NOT NULL,
    label           TEXT,
    payload         JSONB NOT NULL DEFAULT '{}'::JSONB,
    archived_by     BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    archived_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at      TIMESTAMPTZ NOT NULL DEFAULT (NOW()+INTERVAL '30 days'),
    restored_at     TIMESTAMPTZ,
    permanently_deleted_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS archive_items_active_idx ON archive_items(expires_at,archived_at DESC) WHERE restored_at IS NULL AND permanently_deleted_at IS NULL;

-- Lightweight activity analytics for the administration dashboard.
CREATE TABLE IF NOT EXISTS analytics_events (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id      BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    visitor_kind    VARCHAR(20) NOT NULL DEFAULT 'anonymous',
    event_type      VARCHAR(60) NOT NULL,
    entity_type     VARCHAR(40),
    entity_id       TEXT,
    metadata        JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS analytics_events_time_idx ON analytics_events(created_at DESC,event_type);

CREATE TABLE IF NOT EXISTS member_presence_sessions (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    connected_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    disconnected_at TIMESTAMPTZ,
    seconds_online  BIGINT NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS member_presence_account_idx ON member_presence_sessions(account_id,connected_at DESC);

-- Record the current migration version without replacing existing environments.
INSERT INTO schema_state(key,value) VALUES('workspace_revision','2026-09-12')
ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=NOW();

-- ===== AITS collaboration + moderation expansion (2026-09 final) =====
CREATE UNIQUE INDEX IF NOT EXISTS conversations_one_organization
    ON conversations (conversation_type) WHERE conversation_type='community';
CREATE UNIQUE INDEX IF NOT EXISTS conversations_one_per_division
    ON conversations (division_id) WHERE conversation_type='group' AND division_id IS NOT NULL;

ALTER TABLE member_presence_sessions ADD COLUMN IF NOT EXISTS last_seen_at TIMESTAMPTZ;
ALTER TABLE divisions ADD COLUMN IF NOT EXISTS assessment_enabled BOOLEAN NOT NULL DEFAULT TRUE;

-- Compatibility columns used by the current Admin/Application assessment workspace.
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS question_text TEXT;
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS sort_order INTEGER NOT NULL DEFAULT 0;
ALTER TABLE assessment_questions ALTER COLUMN prompt SET DEFAULT '';
UPDATE assessment_questions SET question_text=COALESCE(NULLIF(question_text,''),prompt,'') WHERE COALESCE(question_text,'')='';

ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS correct_answer TEXT;
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS dummy_answers JSONB NOT NULL DEFAULT '[]'::JSONB;

-- Administration is rendered as a single ordered directory. The legacy category column
-- remains for backward compatibility and is not exposed in the management experience.
ALTER TABLE administration_members ALTER COLUMN category SET DEFAULT 'officer';
ALTER TABLE administration_members ALTER COLUMN position_title SET DEFAULT 'Member';

-- Expired archive snapshots are purged by the Go backend so managed Library files
-- can be removed from disk together with their archive records.

INSERT INTO schema_state(key,value) VALUES('workspace_revision','2026-09-12-final')
ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=NOW();

-- ===== AITS index/admin chat, media safety, bug reports, and assessment content (2026-09-13) =====
ALTER TABLE support_messages ADD COLUMN IF NOT EXISTS seen_by_visitor_at TIMESTAMPTZ;
ALTER TABLE support_messages ADD COLUMN IF NOT EXISTS seen_by_admin_at TIMESTAMPTZ;

CREATE TABLE IF NOT EXISTS bug_reports (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reporter_account_id BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    reporter_name       VARCHAR(180),
    reporter_email      VARCHAR(255),
    summary             VARCHAR(220) NOT NULL,
    description         TEXT NOT NULL,
    page_url            TEXT,
    user_agent          TEXT,
    status              VARCHAR(20) NOT NULL DEFAULT 'open' CHECK (status IN ('open','reviewing','resolved','closed')),
    admin_note          TEXT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS bug_reports_status_idx ON bug_reports(status,created_at DESC);

ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS assessment_kind VARCHAR(30) NOT NULL DEFAULT 'qa';
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS question_content JSONB NOT NULL DEFAULT '{}'::JSONB;
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS correct_answer_content JSONB NOT NULL DEFAULT '{}'::JSONB;
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS dummy_answer_contents JSONB NOT NULL DEFAULT '[]'::JSONB;
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS assessment_metadata JSONB NOT NULL DEFAULT '{}'::JSONB;
UPDATE assessment_questions
SET question_content = CASE WHEN question_content='{}'::jsonb THEN jsonb_build_object('type','text','text',question_text) ELSE question_content END,
    correct_answer_content = CASE WHEN correct_answer_content='{}'::jsonb THEN jsonb_build_object('type','text','text',COALESCE(correct_answer,'')) ELSE correct_answer_content END,
    dummy_answer_contents = CASE WHEN dummy_answer_contents='[]'::jsonb THEN COALESCE((SELECT jsonb_agg(jsonb_build_object('type','text','text',value)) FROM jsonb_array_elements_text(dummy_answers) AS value),'[]'::jsonb) ELSE dummy_answer_contents END;

INSERT INTO media_library(label,media_type,url,visibility,is_active,location_label,reason,source_type)
SELECT seed.label,'image',seed.url,'public',TRUE,'Branding',seed.reason,'path'
FROM (VALUES
    ('AITS logo','/icons/aits.svg','Primary AITS identity asset.'),
    ('CodeHex division logo','/icons/division-codehex.svg','CodeHex division identity asset.'),
    ('Illustrados division logo','/icons/division-illustrados.svg','Illustrados division identity asset.'),
    ('Neo-Tech division logo','/icons/division-neotech.svg','Neo-Tech division identity asset.'),
    ('Bug report icon','/icons/report-bug.svg','Shared report-a-bug icon.')
) AS seed(label,url,reason)
WHERE NOT EXISTS (SELECT 1 FROM media_library ml WHERE ml.url=seed.url);

UPDATE divisions SET logo_url=CASE code
    WHEN 'codehex' THEN '/icons/division-codehex.svg'
    WHEN 'illustrados' THEN '/icons/division-illustrados.svg'
    WHEN 'neo-tech' THEN '/icons/division-neotech.svg'
    ELSE logo_url END
WHERE COALESCE(logo_url,'')='';

INSERT INTO schema_state(key,value) VALUES('workspace_revision','2026-09-13-index-admin-chat')
ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=NOW();

COMMIT;


