ALTER TABLE assessment_questions DROP CONSTRAINT IF EXISTS assessment_questions_year_level_check;
ALTER TABLE assessment_questions ADD CONSTRAINT assessment_questions_year_level_check CHECK (year_level BETWEEN 1 AND 4);
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS seed_key VARCHAR(120);
CREATE UNIQUE INDEX IF NOT EXISTS assessment_questions_seed_key_unique ON assessment_questions(seed_key) WHERE seed_key IS NOT NULL;
