-- Applicant-to-member one-time activation links.
CREATE TABLE IF NOT EXISTS member_activation_invites (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id  BIGINT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    token_hash      VARCHAR(128) NOT NULL UNIQUE,
    division_id     BIGINT REFERENCES divisions(id) ON DELETE SET NULL,
    role_id         BIGINT NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,
    membership      VARCHAR(40) NOT NULL DEFAULT 'Member',
    created_by      BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    expires_at      TIMESTAMPTZ NOT NULL,
    used_at         TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS member_activation_invites_application_idx ON member_activation_invites(application_id, expires_at DESC);

COMMIT;

BEGIN;

-- ===== Supplied AITS/BCC/CITE/division branding + assessment integrity (2026-09-17) =====
ALTER TABLE assessment_attempt_items ADD COLUMN IF NOT EXISTS selected_answer_text TEXT;
ALTER TABLE assessment_attempt_items ADD COLUMN IF NOT EXISTS selected_answer_key TEXT;

-- Register the supplied PNG identities in the same managed Library used by uploads.
INSERT INTO media_library(label,media_type,url,visibility,is_active,location_label,reason,source_type,extension,file_size,content_hash,division_id)
SELECT seed.label,seed.media_type,seed.url,'public',TRUE,seed.location_label,seed.reason,seed.source_type,seed.extension,seed.file_size,seed.content_hash,
       CASE WHEN seed.division_code IS NULL THEN NULL ELSE (SELECT id FROM divisions WHERE code=seed.division_code) END
FROM (VALUES
    ('AITS logo','image','/library/images/branding/aits.png','Branding','Primary AITS identity asset used across public, member, admin, and application UI.','bundled','png',1519832,'1418b14ed81abd497c28aad624399a2d6c5afeee122ad5ca83f9dc5893465555',NULL),
    ('Buenavista Community College seal','image','/library/images/branding/bcc.png','Branding','Buenavista Community College institutional identity asset.','bundled','png',4853524,'27285993b0f5edc8a981a1a46fa29daa9121ed23102de5487bc4dbb03c412d02',NULL),
    ('CITE identity','image','/library/images/branding/cite.png','Branding','Information Technology / CITE institutional identity asset.','bundled','png',2092103,'4050f4d20614fe1ffeebc5ba7b055f26539131597c18554c4dc6e23956865fd7',NULL),
    ('CodeHex division logo','image','/library/images/divisions/codehex.png','Divisions','Official CodeHex division identity asset.','bundled','png',1304863,'f391884f4d31ab7d66e8fbe5db322ddd377d5a8be9e65157ee8e58a623c8dc09','codehex'),
    ('Illustrados division logo','image','/library/images/divisions/illustrados.png','Divisions','Official Illustrados division identity asset.','bundled','png',1024578,'3936c15d97dcf57b72cd4ee09a5c659752d9575efb9530463ca4ada982680813','illustrados'),
    ('Neo-Tech division logo','image','/library/images/divisions/neotech.png','Divisions','Official Neo-Tech division identity asset.','bundled','png',1459950,'83b9c210c052d82654a4af8980a9625e7d77aaa1d9c242fb48219a5404fb57f3','neo-tech')
) AS seed(label,media_type,url,location_label,reason,source_type,extension,file_size,content_hash,division_code)
WHERE NOT EXISTS (SELECT 1 FROM media_library ml WHERE ml.url=seed.url);

-- Keep Library metadata current even when this idempotent schema runs again.
UPDATE media_library SET
    label=seed.label,
    media_type=seed.media_type,
    visibility='public',
    is_active=TRUE,
    location_label=seed.location_label,
    reason=seed.reason,
    source_type=seed.source_type,
    extension=seed.extension,
    file_size=seed.file_size,
    content_hash=seed.content_hash,
    division_id=CASE WHEN seed.division_code IS NULL THEN NULL ELSE (SELECT id FROM divisions WHERE code=seed.division_code) END,
    updated_at=NOW()
FROM (VALUES
    ('AITS logo','image','/library/images/branding/aits.png','Branding','Primary AITS identity asset used across public, member, admin, and application UI.','bundled','png',1519832,'1418b14ed81abd497c28aad624399a2d6c5afeee122ad5ca83f9dc5893465555',NULL),
    ('Buenavista Community College seal','image','/library/images/branding/bcc.png','Branding','Buenavista Community College institutional identity asset.','bundled','png',4853524,'27285993b0f5edc8a981a1a46fa29daa9121ed23102de5487bc4dbb03c412d02',NULL),
    ('CITE identity','image','/library/images/branding/cite.png','Branding','Information Technology / CITE institutional identity asset.','bundled','png',2092103,'4050f4d20614fe1ffeebc5ba7b055f26539131597c18554c4dc6e23956865fd7',NULL),
    ('CodeHex division logo','image','/library/images/divisions/codehex.png','Divisions','Official CodeHex division identity asset.','bundled','png',1304863,'f391884f4d31ab7d66e8fbe5db322ddd377d5a8be9e65157ee8e58a623c8dc09','codehex'),
    ('Illustrados division logo','image','/library/images/divisions/illustrados.png','Divisions','Official Illustrados division identity asset.','bundled','png',1024578,'3936c15d97dcf57b72cd4ee09a5c659752d9575efb9530463ca4ada982680813','illustrados'),
    ('Neo-Tech division logo','image','/library/images/divisions/neotech.png','Divisions','Official Neo-Tech division identity asset.','bundled','png',1459950,'83b9c210c052d82654a4af8980a9625e7d77aaa1d9c242fb48219a5404fb57f3','neo-tech')
) AS seed(label,media_type,url,location_label,reason,source_type,extension,file_size,content_hash,division_code)
WHERE media_library.url=seed.url;

-- Use the supplied division logos, but do not overwrite an administrator-selected custom logo.
UPDATE divisions SET logo_url=CASE code
    WHEN 'codehex' THEN '/library/images/divisions/codehex.png'
    WHEN 'illustrados' THEN '/library/images/divisions/illustrados.png'
    WHEN 'neo-tech' THEN '/library/images/divisions/neotech.png'
    ELSE logo_url END,
    updated_at=NOW()
WHERE COALESCE(logo_url,'')='' OR logo_url IN (
    '/icons/division-codehex.svg',
    '/icons/division-illustrados.svg',
    '/icons/division-neotech.svg'
);

-- Move bundled sample-post media to the supplied managed identities.
UPDATE posts SET media = '[{"type":"image","src":"/library/images/branding/aits.png","name":"AITS community"},{"type":"image","src":"/library/images/divisions/codehex.png","name":"CodeHex"},{"type":"image","src":"/library/images/divisions/illustrados.png","name":"Illustrados"},{"type":"image","src":"/library/images/divisions/neotech.png","name":"Neo-Tech"}]'::jsonb WHERE seed_key = 'sample-post-01';
UPDATE posts SET media = '[{"type":"image","src":"/library/images/divisions/codehex.png","name":"CodeHex"}]'::jsonb WHERE seed_key = 'sample-post-02';
UPDATE posts SET media = '[{"type":"image","src":"/library/images/divisions/illustrados.png","name":"Illustrados"}]'::jsonb WHERE seed_key = 'sample-post-03';
UPDATE posts SET media = '[{"type":"image","src":"/library/images/divisions/neotech.png","name":"Neo-Tech"}]'::jsonb WHERE seed_key = 'sample-post-04';

-- Retire only obsolete bundled placeholder records that are not referenced by assessment content.
DELETE FROM media_library ml
WHERE ml.url IN (
    '/icons/aits.svg',
    '/icons/division-codehex.svg',
    '/icons/division-illustrados.svg',
    '/icons/division-neotech.svg',
    '/imgs/blog-aits.svg',
    '/imgs/blog-codehex.svg',
    '/imgs/blog-illustrados.svg',
    '/imgs/blog-neotech.svg'
)
AND NOT EXISTS (
    SELECT 1 FROM assessment_questions q
    WHERE q.question_content->>'library_id'=ml.id::text
       OR q.correct_answer_content->>'library_id'=ml.id::text
       OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(COALESCE(q.dummy_answer_contents,'[]'::jsonb)) d
           WHERE d->>'library_id'=ml.id::text
       )
);

INSERT INTO schema_state(key,value) VALUES('workspace_revision','2026-09-17-branding-integrity-v5')
ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=NOW();

COMMIT;


BEGIN;
-- ===== Membership invitations, restrictions, and presence details (2026-09-19) =====
ALTER TABLE member_activation_invites ALTER COLUMN application_id DROP NOT NULL;
ALTER TABLE member_activation_invites ALTER COLUMN account_id DROP NOT NULL;
ALTER TABLE member_activation_invites ADD COLUMN IF NOT EXISTS invite_kind VARCHAR(24) NOT NULL DEFAULT 'application';
ALTER TABLE member_activation_invites ADD COLUMN IF NOT EXISTS invite_name TEXT;
ALTER TABLE member_activation_invites ADD COLUMN IF NOT EXISTS invite_email TEXT;
ALTER TABLE member_activation_invites ADD COLUMN IF NOT EXISTS invite_username VARCHAR(80);
ALTER TABLE member_activation_invites ADD COLUMN IF NOT EXISTS invite_password_hash TEXT;
ALTER TABLE member_activation_invites ADD COLUMN IF NOT EXISTS invite_password_cipher TEXT;
CREATE INDEX IF NOT EXISTS member_activation_invites_email_active_idx ON member_activation_invites((LOWER(invite_email)), expires_at DESC) WHERE used_at IS NULL;
CREATE INDEX IF NOT EXISTS member_activation_invites_username_active_idx ON member_activation_invites((LOWER(invite_username)), expires_at DESC) WHERE used_at IS NULL;

CREATE TABLE IF NOT EXISTS member_restrictions (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id      BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    reason          TEXT NOT NULL,
    restricted_by   BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    restricted_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    lifts_at        TIMESTAMPTZ,
    lifted_at       TIMESTAMPTZ,
    lifted_by       BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS member_restrictions_active_idx ON member_restrictions(account_id, restricted_at DESC) WHERE lifted_at IS NULL;

INSERT INTO schema_state(key,value) VALUES('workspace_revision','2026-09-19-member-invites-restrictions-v1')
ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=NOW();
COMMIT;

-- 2026-09 member social/chat upgrades.
ALTER TABLE messages ADD COLUMN IF NOT EXISTS unsent_at TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS message_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    message_id BIGINT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
    editor_account_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    body TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS message_history_message_idx ON message_history(message_id,id DESC);
ALTER TABLE message_reactions ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
-- One reaction per account per message. Keep the latest legacy reaction before changing the key.
DELETE FROM message_reactions older USING message_reactions newer
WHERE older.message_id=newer.message_id AND older.account_id=newer.account_id
  AND (older.created_at<newer.created_at OR (older.created_at=newer.created_at AND older.ctid<newer.ctid));
ALTER TABLE message_reactions DROP CONSTRAINT IF EXISTS message_reactions_pkey;
ALTER TABLE message_reactions ADD CONSTRAINT message_reactions_pkey PRIMARY KEY(message_id,account_id);

-- Visitor support follows the same one-reaction-per-account rule.
DELETE FROM support_message_reactions older USING support_message_reactions newer
WHERE older.message_id=newer.message_id AND older.account_id=newer.account_id
  AND (older.created_at<newer.created_at OR (older.created_at=newer.created_at AND older.ctid<newer.ctid));
ALTER TABLE support_message_reactions DROP CONSTRAINT IF EXISTS support_message_reactions_pkey;
ALTER TABLE support_message_reactions ADD CONSTRAINT support_message_reactions_pkey PRIMARY KEY(message_id,account_id);

ALTER TABLE posts ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS post_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    post_id BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    editor_account_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    title TEXT,
    body TEXT NOT NULL,
    visibility VARCHAR(20) NOT NULL,
    identity_kind VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS post_history_post_idx ON post_history(post_id,id DESC);

-- 2026-09-21 member chat polls.
CREATE TABLE IF NOT EXISTS chat_polls (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conversation_id BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    creator_account_id BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
    question VARCHAR(500) NOT NULL,
    closes_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS chat_polls_conversation_idx ON chat_polls(conversation_id,id DESC);
CREATE TABLE IF NOT EXISTS chat_poll_options (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    poll_id BIGINT NOT NULL REFERENCES chat_polls(id) ON DELETE CASCADE,
    option_text VARCHAR(240) NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS chat_poll_options_poll_idx ON chat_poll_options(poll_id,sort_order,id);
CREATE TABLE IF NOT EXISTS chat_poll_votes (
    poll_id BIGINT NOT NULL REFERENCES chat_polls(id) ON DELETE CASCADE,
    option_id BIGINT NOT NULL REFERENCES chat_poll_options(id) ON DELETE CASCADE,
    account_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY(poll_id,account_id)
);
CREATE INDEX IF NOT EXISTS chat_poll_votes_option_idx ON chat_poll_votes(option_id);
ALTER TABLE messages ADD COLUMN IF NOT EXISTS poll_id BIGINT REFERENCES chat_polls(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS messages_poll_idx ON messages(poll_id) WHERE poll_id IS NOT NULL;


-- ===== Expanded balanced division assessment bank (2026-10-01) =====
